node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import pg from 'pg';

const { Pool } = pg;
const pool = new Pool({ connectionString: 'postgresql://forkity:forkity_dev@localhost:5432/forkity' });
const email = `stage3-${Date.now()}@example.test`;
const password = 'A-long-test-password-123';
let cookie;

const request = async (path, payload) => {
  const response = await fetch(`http://localhost:3000/api/v1/auth/${path}`, {
    method: payload ? 'POST' : 'GET',
    headers: {
      ...(payload && { 'content-type': 'application/json' }),
      ...(cookie && { cookie }),
    },
    ...(payload && { body: JSON.stringify(payload) }),
  });
  const setCookie = response.headers.getSetCookie()[0];
  if (setCookie) cookie = setCookie.split(';')[0];
  const data = response.status === 204 ? null : await response.json();
  return { status: response.status, data, setCookie };
};

try {
  const registered = await request('register', { email, password });
  assert.equal(registered.status, 201);
  assert.match(registered.setCookie, /HttpOnly/i);
  assert.equal(registered.data.user.email, email);
  assert.equal('password_hash' in registered.data.user, false);

  assert.equal((await request('me')).data.user.email, email);
  assert.equal((await request('register', { email: email.toUpperCase(), password })).status, 409);
  assert.equal((await request('login', { email, password: 'incorrect-password' })).status, 401);

  const loggedIn = await request('login', { email, password });
  assert.equal(loggedIn.status, 200);
  assert.notEqual(loggedIn.setCookie.split(';')[0], registered.setCookie.split(';')[0]);
  assert.equal((await request('logout', {})).status, 204);
  assert.equal((await request('me')).data.user, null);
  console.log('Auth flow passed: registration, case-insensitive duplicate, login, session rotation, logout, and unauthenticated current-user state.');
} finally {
  await pool.query('DELETE FROM users WHERE email = $1', [email]);
  await pool.end();
}
NODE

