const controlRecipes = async function () {
  try {

    const id = window.location.hash.slice(1);

    if (!id) return;

    recipeView.renderSpinner();

    //* update results view to update selected search result
    resultsView.update(model.getSearchResultsPage())

    //* update bookmarks view from localhost
    bookmarksView.update(model.state.bookmarks)

    //* Load recipe.
    await model.loadRecipe(id);

    //* Render recipe
    recipeView.render(model.state.recipe);

  }
  catch (err) {
    console.log(`controlRecipes Error 😎: ${err}`);
    recipeView.renderError();
  }

  // for TESTING
  controlServings();
}

const controlSearchResults = async () => {
  try {
    resultsView.renderSpinner();
    //* get search query
    const query = searchView.getQuery();
    if (!query) return;

    //* set state with new search results
    await model.loadSearchResults(query);

    //* render results
    resultsView.render(model.getSearchResultsPage());

    //* render pagination buttons
    paginationView.render(model.state.search);

  }catch(err) {
    console.log(`controlSearchResults Error 😎: ${err}`);
  }
}

const controlPagination = function(goToPage) {
      //* render new results
      resultsView.render(model.getSearchResultsPage(goToPage));

      //* render new pagination buttons
      paginationView.render(model.state.search);
}

const controlServings = function(newServings = model.state.recipe.servings) {
  //* update the recipe servings (in state)
  model.updateServings(newServings)

  //* update the recipe view
  // recipeView.render(model.state.recipe);
  recipeView.update(model.state.recipe);
}

const controlAddBookmark = function() {
  // adds or removes bookmark at the current recipe (boolean)
if(!model.state.recipe.bookmarked) 
  model.addBookmark(model.state.recipe)
else model.deleteBookmark(model.state.recipe.id)

console.log(model.state.recipe);
  // updates recipeView with new bookmark data
  recipeView.update(model.state.recipe)

  // render the bookmarks
  bookmarksView.render(model.state.bookmarks)
}

const controlBookmarks = function() {
  bookmarksView.render(model.state.bookmarks)
}

const controlAddRecipe = async function(newRecipe) {
  try {
  // Show loading spinner
  addRecipeView.renderSpinner()

  // Upload the new recipe data
  await model.uploadRecipe(newRecipe)
  console.log('model.state.recipe: ', model.state.recipe);

  // Render recipe
  recipeView.render(model.state.recipe);

  // Success message
  addRecipeView.renderMessage();

  // Render bookmark view
  bookmarksView.render(model.state.bookmarks);

  // Change id in the url
  window.history.pushState(null, '', `#${model.state.recipe.id}`)

  // Close form window
  setTimeout(function() {
    addRecipeView.toggleWindow()
  }, MODAL_CLOSE_SEC * 1000)

  } catch(err) {
    console.log('🤪', err);
    addRecipeView.renderError(err.message)
  }
}

const controlAuthSubmit = async function({ email, password, mode }) {
  const credentials = { email, password };
  const user = mode === 'register'
    ? await model.registerUser(credentials)
    : await model.loginUser(credentials);

  authView.render(user);
}

const controlAuthLogout = async function() {
  await model.logoutUser();
  authView.render(null);
  authView.close();
}

const controlCurrentUser = async function() {
  try {
    await model.loadCurrentUser();
    authView.render(model.state.user);
  } catch (err) {
    console.error(`Unable to restore account session: ${err.message}`);
  }
}

