import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { createServer } from 'node:http';

let upstreamRequest;
const upstream = createServer(async (request, response) => {
  let body = '';
  for await (const chunk of request) body += chunk;
  upstreamRequest = { method: request.method, url: new URL(request.url, 'http://localhost'), body };
  response.setHeader('content-type', 'application/json');
  response.end(JSON.stringify({ data: { recipes: [{ id: 'mock' }], recipe: { id: 'mock' } } }));
});
await new Promise((resolve) => upstream.listen(4311, '127.0.0.1', resolve));

const api = spawn('node', ['src/server.js'], {
  env: {
    ...process.env,
    PORT: '3311',
    DATABASE_URL: 'postgresql://forkity:forkity_dev@localhost:5432/forkity',
    SESSION_SECRET: 'stage4-integration-test-secret-0123456789',
    FORKIFY_API_URL: 'http://127.0.0.1:4311/api/v2/recipes/',
    FORKIFY_API_KEY: 'server-only-test-key',
  },
  stdio: ['ignore', 'pipe', 'inherit'],
});

try {
  await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('API did not start')), 5000);
    api.stdout.on('data', (chunk) => {
      if (chunk.toString().includes('API listening')) {
        clearTimeout(timeout);
        resolve();
      }
    });
    api.once('exit', (code) => reject(new Error(`API exited early with ${code}`)));
  });

  const origin = 'http://127.0.0.1:3311/api/v1/recipes';
  const searchResponse = await fetch(`${origin}?search=tomato%20soup`);
  assert.equal(searchResponse.status, 200);
  assert.equal((await searchResponse.json()).data.recipes[0].id, 'mock');
  assert.equal(upstreamRequest.method, 'GET');
  assert.equal(upstreamRequest.url.searchParams.get('search'), 'tomato soup');
  assert.equal(upstreamRequest.url.searchParams.get('key'), 'server-only-test-key');

  const recipeResponse = await fetch(`${origin}/recipe-123`);
  assert.equal(recipeResponse.status, 200);
  assert.equal(upstreamRequest.url.pathname, '/api/v2/recipes/recipe-123');

  const recipePayload = { title: 'Mock meal', servings: 3, ingredients: [] };
  const uploadResponse = await fetch(origin, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(recipePayload),
  });
  assert.equal(uploadResponse.status, 200);
  assert.equal(upstreamRequest.method, 'POST');
  assert.deepEqual(JSON.parse(upstreamRequest.body), recipePayload);
  assert.equal(upstreamRequest.url.searchParams.get('key'), 'server-only-test-key');

  const invalidSearch = await fetch(`${origin}?search=`);
  assert.equal(invalidSearch.status, 400);
  console.log('Recipe proxy passed: search, detail, upload, server-side API key injection, payload preservation, and input validation.');
} finally {
  api.kill('SIGTERM');
  await new Promise((resolve) => api.once('exit', resolve));
  await new Promise((resolve, reject) => upstream.close((error) => error ? reject(error) : resolve()));
}
