//& Lesson: Refactoring for MVC (Model - View - Controller)
//~ The model part (module): holds the program state and state manipulation functions, holds the business logic and holds the HTTP library to connect to outside resources on the web. this part listens to changes in the state and reacts on them.
//~ The view part (class) (module): responsible for presentation logic and rendering.
//~ The controller part (module): responsible for application logic, it acts as a bridge between the model and the view parts. also helps separate the view from the model and the data. this part handles UI events and dispatches tasks to the model and the view parts.
//~ So the execution goes from the user to the controller which in its turn runs processes in the model and view parts. the data on the other hand flows from the web or any API to the model and together with the data from the state they are passed to the controller which uses this data to give instructions to the view part and render to the screen according to the state and state changes triggered by the user.


import * as model from './model.js';
import { MODAL_CLOSE_SEC } from './config.js';
import recipeView from './views/recipeView.js';
import searchView from './views/searchView.js';
import resultsView from './views/resultsView.js';
import paginationView from './views/paginationView.js';
import bookmarksView from './views/bookmarksView.js';
import addRecipeView from './views/addRecipeView.js';
import authView from './views/authView.js';

import 'core-js/stable';
import 'regenerator-runtime/runtime';

let accountReady = Promise.resolve();

// if (module.hot) {
//   module.hot.accept();
// }

const controlRecipes = async function () {
  try {
    await accountReady;

    const id = window.location.hash.slice(1);

    if (!id) return;

    recipeView.renderSpinner();

    //* update results view to update selected search result
    resultsView.update(model.getSearchResultsPage())

    //* Load recipe.
    await model.loadRecipe(id);

    //* Render recipe
    recipeView.render(model.state.recipe);

  }
  catch (err) {
    console.log(`controlRecipes Error 😎: ${err}`);
    recipeView.renderError();
  }

  // for TESTING
  controlServings();
}

const controlSearchResults = async () => {
  try {
    resultsView.renderSpinner();
    //* get search query
    const query = searchView.getQuery();
    if (!query) return;

    //* set state with new search results
    await model.loadSearchResults(query);

    //* render results
    resultsView.render(model.getSearchResultsPage());

    //* render pagination buttons
    paginationView.render(model.state.search);

  }catch(err) {
    console.log(`controlSearchResults Error 😎: ${err}`);
    resultsView.renderError(err.message);
  }
}

const controlPagination = function(goToPage) {
      //* render new results
      resultsView.render(model.getSearchResultsPage(goToPage));

      //* render new pagination buttons
      paginationView.render(model.state.search);
}

const controlServings = function(newServings = model.state.recipe.servings) {
  //* update the recipe servings (in state)
  model.updateServings(newServings)

  //* update the recipe view
  // recipeView.render(model.state.recipe);
  recipeView.update(model.state.recipe);
}

const controlAddBookmark = async function() {
  if (!model.state.user) {
    authView.openLogin();
    return;
  }

  try {
    if (!model.state.recipe.bookmarked) await model.addBookmark(model.state.recipe);
    else await model.deleteBookmark(model.state.recipe.id);

    recipeView.update(model.state.recipe);
    bookmarksView.render(model.state.bookmarks);
  } catch (err) {
    window.alert(err.message);
  }
}

const controlBookmarks = function() {
  if (!model.state.user) {
    bookmarksView.renderEmpty('Log in to save bookmarks to your account.');
    return;
  }
  bookmarksView.render(model.state.bookmarks)
}

const controlAddRecipe = async function(newRecipe) {
  if (!model.state.user) {
    authView.openLogin();
    return;
  }

  try {
  // Show loading spinner
  addRecipeView.renderSpinner()

  // Upload the new recipe data
  await model.uploadRecipe(newRecipe)
  console.log('model.state.recipe: ', model.state.recipe);

  // Render recipe
  recipeView.render(model.state.recipe);

  // Success message
  addRecipeView.renderMessage();

  // Render bookmark view
  bookmarksView.render(model.state.bookmarks);

  // Change id in the url
  window.history.pushState(null, '', `#${model.state.recipe.id}`)

  // Close form window
  setTimeout(function() {
    addRecipeView.toggleWindow()
  }, MODAL_CLOSE_SEC * 1000)

  } catch(err) {
    console.log('🤪', err);
    addRecipeView.renderError(err.message)
  }
}

const controlAuthSubmit = async function({ email, password, mode }) {
  const credentials = { email, password };
  const user = mode === 'register'
    ? await model.registerUser(credentials)
    : await model.loginUser(credentials);

  await model.loadBookmarks();
  bookmarksView.render(model.state.bookmarks);
  if (model.state.recipe.id) recipeView.update(model.state.recipe);
  authView.render(user);
}

const controlAuthLogout = async function() {
  await model.logoutUser();
  authView.render(null);
  bookmarksView.renderEmpty('Log in to save bookmarks to your account.');
  if (model.state.recipe.id) recipeView.update(model.state.recipe);
  authView.close();
}

const controlCurrentUser = async function() {
  try {
    const user = await model.loadCurrentUser();
    if (user) await model.loadBookmarks();
    authView.render(user);
    if (user) bookmarksView.render(model.state.bookmarks);
    else bookmarksView.renderEmpty('Log in to save bookmarks to your account.');
  } catch (err) {
    console.error(`Unable to restore account session: ${err.message}`);
  }
}

const init = function() {
  bookmarksView.addHandlerRender(controlBookmarks)
  recipeView.addHandlerRender(controlRecipes);
  recipeView.addHandlerUpdateServings(controlServings);
  recipeView.addHandlerAddBookmark(controlAddBookmark);
  searchView.addHandlerSearch(controlSearchResults);
  paginationView.addHandlerClick(controlPagination);
  addRecipeView.addHandlerUpload(controlAddRecipe);
  authView.addHandlerSubmit(controlAuthSubmit);
  authView.addHandlerLogout(controlAuthLogout);
  console.log('Welcome!');
}
init();
accountReady = controlCurrentUser();

