import dotenv from 'dotenv';
import pg from 'pg';

const env = dotenv.parse(fs.readFileSync('.env'));
const { Pool } = pg;
const pool = new Pool({ connectionString: env.DATABASE_URL });
const origin = 'http://localhost:1234/api/v1';
const email = `browser-check-${randomUUID()}@example.test`;
let cookie;

const request = async (path, { method = 'GET', payload } = {}) => {
  const response = await fetch(`${origin}${path}`, {
    method,
    headers: {
      ...(payload && { 'content-type': 'application/json' }),
      ...(cookie && { cookie }),
    },
    ...(payload && { body: JSON.stringify(payload) }),
  });
  const setCookie = response.headers.getSetCookie()[0];
  if (setCookie) cookie = setCookie.split(';')[0];
  return { response, data: response.status === 204 ? null : await response.json() };
};

try {
  assert.equal((await request('/auth/register', {
    method: 'POST', payload: { email, password: 'Browser-check-password-123' },
  })).response.status, 201);
  const saved = await request('/recipes', {
    method: 'POST',
    payload: {
      title: 'Browser local recipe',
      publisher: 'Local test',
      source_url: 'https://example.test/recipe',
      image_url: 'https://example.test/recipe.jpg',
      servings: 2,
      cooking_time: 20,
      ingredients: [{ quantity: 1, unit: 'cup', description: 'test ingredient' }],
    },
  });
  assert.equal(saved.response.status, 201);
  const localId = saved.data.data.recipe.id;
  assert.equal((await request(`/recipes/${localId}`)).data.data.recipe.title, 'Browser local recipe');
  assert.equal((await request('/bookmarks')).data.bookmarks[0].id, localId);
  await request('/auth/logout', { method: 'POST', payload: {} });
  console.log('Live app proxy passed: register, local recipe save, owner detail read, bookmark, and logout.');
} finally {
  await pool.query('DELETE FROM users WHERE email = $1', [email]);
  await pool.end();
}
