//& Lesson: Refactoring for MVC (Model - View - Controller)
//~ Encapsulating the model part
//~ By using export on the state variable it will automatically update the variable on the import side which is the controller in this case. 

import { async } from 'regenerator-runtime';
import { API_URL, AUTH_API_URL, RESULTS_PER_PAGE } from './config.js';
// import { getJSON, sendJSON } from './helpers.js';
import { AJAX } from './helpers.js'
// import { search } from 'core-js/fn/symbol';



//* initialize state
export const state = {
  user: null,
  recipe: {},
  search: {
    query: '',
    results: [],
    pageNum: 1,
    resultsPerPage: RESULTS_PER_PAGE,
  },
  bookmarks: [],
};

const authRequest = async (endpoint, payload) => {
  const response = await fetch(`${AUTH_API_URL}/${endpoint}`, {
    method: payload === undefined ? 'GET' : 'POST',
    credentials: 'same-origin',
    headers: payload === undefined ? undefined : { 'Content-Type': 'application/json' },
    body: payload === undefined ? undefined : JSON.stringify(payload),
  });

  const data = response.status === 204 ? null : await response.json();
  if (!response.ok) throw new Error(data?.message || 'Unable to complete the account request.');
  return data;
};

const bookmarkRequest = async (path, method = 'GET', payload) => {
  const response = await fetch(`/api/v1/bookmarks${path}`, {
    method,
    credentials: 'same-origin',
    headers: payload === undefined ? undefined : { 'Content-Type': 'application/json' },
    body: payload === undefined ? undefined : JSON.stringify(payload),
  });

  const data = response.status === 204 ? null : await response.json();
  if (!response.ok) throw new Error(data?.message || 'Unable to update bookmarks.');
  return data;
};

export const loadCurrentUser = async () => {
  const { user } = await authRequest('me');
  state.user = user;
  return user;
};

export const registerUser = async (credentials) => {
  const { user } = await authRequest('register', credentials);
  state.user = user;
  return user;
};

export const loginUser = async (credentials) => {
  const { user } = await authRequest('login', credentials);
  state.user = user;
  return user;
};

export const logoutUser = async () => {
  await authRequest('logout', {});
  state.user = null;
  state.bookmarks = [];
  if (state.recipe.id) state.recipe.bookmarked = false;
};

export const loadBookmarks = async () => {
  const { bookmarks } = await bookmarkRequest('');
  state.bookmarks = bookmarks;
  if (state.recipe.id) {
    state.recipe.bookmarked = bookmarks.some((bookmark) => bookmark.id === state.recipe.id);
  }
  return bookmarks;
};

const createRecipeObject = function(data) {
      //* save the recipe 
      const { recipe } = data.data;

      return {
        id: recipe.id,
        title: recipe.title,
        publisher: recipe.publisher,
        sourceUrl: recipe.source_url,
        image: recipe.image_url,
        servings: recipe.servings,
        cookingTime: recipe.cooking_time,
        ingredients: recipe.ingredients,
        ...(recipe.key && {key: recipe.key}),
        bookmarked: Boolean(recipe.bookmarked),
      }
    }

    export const loadRecipe = async function (id) {
      try {

    //* load recipe data
    const data = await AJAX(`${API_URL}/${encodeURIComponent(id)}`);

    state.recipe = createRecipeObject(data);
    state.recipe.bookmarked = state.bookmarks.some(bookmark => bookmark.id === id);

    console.log('recipe in state: ', state.recipe);

  } catch (err) {
    console.error(`loadRecipe Error 😎: ${err}`);
    throw err
  }
}

//* Search
export const loadSearchResults = async (query) => {
  try {

    state.search.query = query;

    const data = await AJAX(`${API_URL}?search=${encodeURIComponent(query)}`);

    state.search.results = data.data.recipes.map(rec => {
      return {
        id: rec.id,
        title: rec.title,
        publisher: rec.publisher,
        image: rec.image_url,
        ...(rec.key && {key: rec.key}),
      }
    })

    state.search.pageNum = 1

  } catch (err) {
    console.log(`loadSearchResults Error 😎: ${err}`);
    throw err
  }
}

export const getSearchResultsPage = (pageNum = state.search.pageNum) => {

  state.search.pageNum = pageNum;

  // dynamic start and end point for slice: lets say we look for page 1, so pageNum = 1.
  const start = (pageNum - 1) * state.search.resultsPerPage // 0
  const end = pageNum * state.search.resultsPerPage // 9

  return state.search.results.slice(start, end)
}


//* Update servings

export const updateServings = function (newServings) {
  state.recipe.ingredients.forEach(ing => {
    ing.quantity = (ing.quantity * newServings) / state.recipe.servings
    // newQt = oldQt * newServings / oldServings
  });

  state.recipe.servings = newServings
}

//* add bookmark
export const addBookmark = async function(recipe) {
  const { bookmark } = await bookmarkRequest('', 'POST', { recipe });
  const index = state.bookmarks.findIndex((saved) => saved.id === bookmark.id);
  if (index === -1) state.bookmarks.push(bookmark);
  else state.bookmarks[index] = bookmark;

  if (recipe.id === state.recipe.id) state.recipe.bookmarked = true;
}

//* remove bookmark
export const deleteBookmark = async function(id) {
  await bookmarkRequest(`/${encodeURIComponent(id)}`, 'DELETE');
  const index = state.bookmarks.findIndex(el => el.id === id)
  if (index !== -1) state.bookmarks.splice(index, 1)

  if (id === state.recipe.id) state.recipe.bookmarked = false
}

export const parseRecipeIngredients = (recipeFields) => Object.entries(recipeFields)
  .filter(([name, value]) => name.startsWith('ingredient') && value.trim())
  .map(([name, value]) => {
    const firstComma = value.indexOf(',');
    const secondComma = value.indexOf(',', firstComma + 1);
    const ingredientNumber = name.replace('ingredient-', '');

    if (firstComma === -1 || secondComma === -1) {
      throw new Error(`Ingredient ${ingredientNumber} must use Quantity,Unit,Description format.`);
    }

    const quantityText = value.slice(0, firstComma).trim();
    const unit = value.slice(firstComma + 1, secondComma).trim();
    const description = value.slice(secondComma + 1).trim();
    const quantity = quantityText ? Number(quantityText) : null;

    if (quantity !== null && (!Number.isFinite(quantity) || quantity < 0)) {
      throw new Error(`Ingredient ${ingredientNumber} quantity must be a non-negative number.`);
    }
    if (!description) {
      throw new Error(`Ingredient ${ingredientNumber} needs a description.`);
    }

    return { quantity, unit, description };
  });

export const uploadRecipe = async function(newRecipe) {
  try {
  const ingredients = parseRecipeIngredients(newRecipe);

  const recipe = {
    title: newRecipe.title,
    source_url: null,
    image_url: null,
    publisher: newRecipe.publisher,
    cooking_time: +newRecipe.cookingTime,
    servings: +newRecipe.servings,
    ingredients,
  }

  const data = await AJAX(API_URL, recipe)

  state.recipe = createRecipeObject(data);
  state.recipe.bookmarked = true;
  state.bookmarks.unshift(state.recipe);

} catch(err) {
  throw err; 
}
}

import 'dotenv/config';
import express from 'express';
import session from 'express-session';
import pg from 'pg';
import connectPgSimple from 'connect-pg-simple';
import bcrypt from 'bcryptjs';
import { randomUUID } from 'node:crypto';

const { Pool } = pg;
const port = Number(process.env.PORT || 3000);
const sessionSecret = process.env.SESSION_SECRET;
const recipeApiUrl = process.env.FORKIFY_API_URL;
const recipeApiTimeout = 10_000;

if (!process.env.DATABASE_URL) {
  throw new Error('DATABASE_URL must be set');
}

if (!sessionSecret || Buffer.byteLength(sessionSecret) < 32) {
  throw new Error('SESSION_SECRET must be set to at least 32 characters');
}

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const app = express();
const PgSession = connectPgSimple(session);
const cookieName = 'forkity.sid';
const cookieOptions = {
  httpOnly: true,
  secure: process.env.NODE_ENV === 'production',
  sameSite: 'lax',
  maxAge: 7 * 24 * 60 * 60 * 1000,
};

app.disable('x-powered-by');
if (process.env.NODE_ENV === 'production') app.set('trust proxy', 1);

app.use(express.json({ limit: '64kb' }));
app.use(session({
  name: cookieName,
  store: new PgSession({
    pool,
    tableName: 'user_sessions',
    createTableIfMissing: false,
  }),
  secret: sessionSecret,
  resave: false,
  saveUninitialized: false,
  rolling: true,
  cookie: cookieOptions,
}));

const validateCredentials = ({ email, password } = {}) => {
  if (typeof email !== 'string' || typeof password !== 'string') return null;

  const normalizedEmail = email.trim().toLowerCase();
  if (
    normalizedEmail.length > 254 ||
    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizedEmail) ||
    password.length < 8 ||
    Buffer.byteLength(password, 'utf8') > 72
  ) {
    return null;
  }

  return { email: normalizedEmail, password };
};

const establishSession = (request, userId) => new Promise((resolve, reject) => {
  request.session.regenerate((regenerateError) => {
    if (regenerateError) return reject(regenerateError);

    request.session.userId = userId;
    request.session.save((saveError) => {
      if (saveError) return reject(saveError);
      resolve();
    });
  });
});

const publicUser = (row) => ({ id: row.id, email: row.email });

const requireAuthentication = (request, response, next) => {
  if (!Number.isInteger(request.session.userId)) {
    return response.status(401).json({ message: 'Log in to access your bookmarks.' });
  }
  next();
};

const normalizeBookmarkRecipe = (recipe) => {
  if (!recipe || typeof recipe !== 'object' || Array.isArray(recipe)) return null;

  const textFields = ['id', 'title', 'publisher'];
  if (textFields.some((field) => typeof recipe[field] !== 'string' || !recipe[field].trim())) return null;
  if (['sourceUrl', 'image'].some((field) => recipe[field] != null && typeof recipe[field] !== 'string')) return null;
  if (recipe.id.length > 128 || recipe.title.length > 300 || recipe.publisher.length > 200) return null;
  if (!Number.isFinite(recipe.servings) || recipe.servings < 1 || recipe.servings > 1000) return null;
  if (!Number.isFinite(recipe.cookingTime) || recipe.cookingTime < 1 || recipe.cookingTime > 10000) return null;
  if (!Array.isArray(recipe.ingredients) || recipe.ingredients.length > 100) return null;

  try {
    for (const field of ['sourceUrl', 'image']) {
      if (!recipe[field]) continue;
      const url = new URL(recipe[field]);
      if (!['http:', 'https:'].includes(url.protocol)) return null;
    }
  } catch {
    return null;
  }

  const ingredients = recipe.ingredients.map((ingredient) => {
    if (!ingredient || typeof ingredient !== 'object') return null;
    if (
      (ingredient.quantity !== null && !Number.isFinite(ingredient.quantity)) ||
      typeof ingredient.unit !== 'string' || ingredient.unit.length > 80 ||
      typeof ingredient.description !== 'string' || ingredient.description.length > 300
    ) return null;

    return {
      quantity: ingredient.quantity,
      unit: ingredient.unit,
      description: ingredient.description,
    };
  });

  if (ingredients.includes(null)) return null;

  return {
    id: recipe.id,
    title: recipe.title,
    publisher: recipe.publisher,
    sourceUrl: recipe.sourceUrl || null,
    image: recipe.image || null,
    servings: recipe.servings,
    cookingTime: recipe.cookingTime,
    ingredients,
    ...(recipe.key ? { key: 'user' } : {}),
    bookmarked: true,
  };
};

app.get('/api/v1/bookmarks', requireAuthentication, async (request, response, next) => {
  try {
    const result = await pool.query(
      'SELECT recipe_data FROM bookmarks WHERE user_id = $1 ORDER BY created_at DESC',
      [request.session.userId],
    );
    response.json({ bookmarks: result.rows.map(({ recipe_data: recipe }) => ({ ...recipe, bookmarked: true })) });
  } catch (error) {
    next(error);
  }
});

app.post('/api/v1/bookmarks', requireAuthentication, async (request, response, next) => {
  const recipe = normalizeBookmarkRecipe(request.body?.recipe);
  if (!recipe) {
    return response.status(400).json({ message: 'A valid recipe is required to create a bookmark.' });
  }

  try {
    const result = await pool.query(
      `INSERT INTO bookmarks (user_id, recipe_id, recipe_data)
       VALUES ($1, $2, $3)
       ON CONFLICT (user_id, recipe_id) DO UPDATE SET recipe_data = EXCLUDED.recipe_data
       RETURNING recipe_data`,
      [request.session.userId, recipe.id, recipe],
    );
    response.status(200).json({ bookmark: result.rows[0].recipe_data });
  } catch (error) {
    next(error);
  }
});

app.delete('/api/v1/bookmarks/:recipeId', requireAuthentication, async (request, response, next) => {
  const { recipeId } = request.params;
  if (!recipeId || recipeId.length > 128) {
    return response.status(400).json({ message: 'A valid recipe ID is required.' });
  }

  try {
    const result = await pool.query(
      'DELETE FROM bookmarks WHERE user_id = $1 AND recipe_id = $2 RETURNING recipe_id',
      [request.session.userId, recipeId],
    );
    if (!result.rowCount) return response.status(404).json({ message: 'Bookmark not found.' });
    response.status(204).end();
  } catch (error) {
    next(error);
  }
});

app.post('/api/v1/auth/register', async (request, response, next) => {
  const credentials = validateCredentials(request.body);
  if (!credentials) {
    return response.status(400).json({
      message: 'Enter a valid email and a password between 8 and 72 bytes.',
    });
  }

  try {
    const passwordHash = await bcrypt.hash(credentials.password, 12);
    let result;

    try {
      result = await pool.query(
        'INSERT INTO users (email, password_hash) VALUES ($1, $2) RETURNING id, email',
        [credentials.email, passwordHash],
      );
    } catch (error) {
      if (error.code === '23505') {
        return response.status(409).json({ message: 'An account with this email already exists.' });
      }
      throw error;
    }

    const user = publicUser(result.rows[0]);
    await establishSession(request, user.id);
    response.status(201).json({ user });
  } catch (error) {
    next(error);
  }
});

app.post('/api/v1/auth/login', async (request, response, next) => {
  const credentials = validateCredentials(request.body);
  if (!credentials) {
    return response.status(400).json({ message: 'Enter a valid email and password.' });
  }

  try {
    const result = await pool.query(
      'SELECT id, email, password_hash FROM users WHERE lower(email) = $1',
      [credentials.email],
    );
    const account = result.rows[0];
    const passwordMatches = account && await bcrypt.compare(credentials.password, account.password_hash);

    if (!passwordMatches) {
      return response.status(401).json({ message: 'Email or password is incorrect.' });
    }

    const user = publicUser(account);
    await establishSession(request, user.id);
    response.json({ user });
  } catch (error) {
    next(error);
  }
});

app.get('/api/v1/auth/me', async (request, response, next) => {
  if (!request.session.userId) return response.json({ user: null });

  try {
    const result = await pool.query(
      'SELECT id, email FROM users WHERE id = $1',
      [request.session.userId],
    );
    response.json({ user: result.rows[0] ? publicUser(result.rows[0]) : null });
  } catch (error) {
    next(error);
  }
});

app.post('/api/v1/auth/logout', (request, response, next) => {
  request.session.destroy((error) => {
    if (error) return next(error);

    response.clearCookie(cookieName, {
      httpOnly: cookieOptions.httpOnly,
      secure: cookieOptions.secure,
      sameSite: cookieOptions.sameSite,
    });
    response.status(204).end();
  });
});

const proxyRecipeRequest = async (request, response) => {
  if (!recipeApiUrl) {
    return response.status(503).json({ message: 'Recipe service is not configured.' });
  }

  const upstreamUrl = new URL(recipeApiUrl);
  if (request.params.id) {
    upstreamUrl.pathname = `${upstreamUrl.pathname.replace(/\/$/, '')}/${encodeURIComponent(request.params.id)}`;
  }
  if (request.query.search) upstreamUrl.searchParams.set('search', request.query.search);
  upstreamUrl.searchParams.delete('key');

  try {
    const upstreamResponse = await fetch(upstreamUrl, {
      method: 'GET',
      signal: AbortSignal.timeout(recipeApiTimeout),
    });
    const data = await upstreamResponse.json();

    if (!upstreamResponse.ok) {
      return response.status(upstreamResponse.status).json({
        message: typeof data.message === 'string' ? data.message : 'Recipe service request failed.',
      });
    }

    response.status(upstreamResponse.status).json(data);
  } catch (error) {
    const isTimeout = error.name === 'TimeoutError' || error.name === 'AbortError';
    response.status(isTimeout ? 504 : 502).json({
      message: isTimeout ? 'Recipe service request timed out.' : 'Recipe service is unavailable.',
    });
  }
};

app.get('/api/v1/recipes', (request, response) => {
  if (typeof request.query.search !== 'string' || !request.query.search.trim() || request.query.search.length > 200) {
    return response.status(400).json({ message: 'A search query between 1 and 200 characters is required.' });
  }
  proxyRecipeRequest(request, response);
});

